// Loads the PNG art generated by tools/make_art.py (assets/manifest.js lists every file and sprite rect).
// Sprites are sliced into offscreen canvases so the renderer can drawImage() them with nearest-neighbour scaling.
const SPR = {};      // sprite name -> canvas, anchored bottom-centre
const SPRMETA = {};  // sprite name -> manifest entry ({ low: hugs the road edge, lift: hovers above the ground, ... })
const STRIP = {};    // parallax strips and canopy -> Image (tile every 960px)

const Assets = {
  message(cv, lines) {
    const c = cv.getContext('2d');
    c.fillStyle = C.ink; c.fillRect(0, 0, VW, VH);
    lines.forEach((s, i) => drawText(c, s, Math.round((VW - textW(s, 3)) / 2), 110 + i * 24, i ? C.stoneL : C.amber, 3));
  },

  load(cv) {
    this.message(cv, ['LOADING']);
    const files = ASSET_MANIFEST.files, imgs = {};
    return Promise.all(Object.keys(files).map(k => new Promise((res, rej) => {
      const im = new Image();
      im.onload = () => { imgs[k] = im; res(); };
      im.onerror = () => rej(new Error('missing ' + files[k]));
      im.src = 'assets/' + files[k];
    }))).then(() => this.build(imgs)).catch(err => { this.message(cv, ['COULD NOT LOAD ART', String(err.message).toUpperCase()]); throw err; });
  },

  build(imgs) {
    for (const [name, d] of Object.entries(ASSET_MANIFEST.sprites)) {
      const c = document.createElement('canvas');
      c.width = d.w; c.height = d.h;
      c.getContext('2d').drawImage(imgs.atlas, d.x, d.y, d.w, d.h, 0, 0, d.w, d.h);
      SPR[name] = c; SPRMETA[name] = d;
    }
    SPR.coin = [0, 1, 2, 3, 4, 5, 6, 7].map(i => SPR['coin' + i]);
    SPR.burst = [0, 1, 2, 3].map(i => SPR['burst' + i]);
    for (const k of Object.keys(ASSET_MANIFEST.strips)) STRIP[k] = imgs[k];
  },
};
